SET UDT_DTTM = SYSDATE

	, SANCTN_STS = #{sanctnSts, jdbcType=VARCHAR}


	, WORK_RPT_YN = #{workRptYn, jdbcType=VARCHAR}

WHERE REQ_NO = #{reqNo, jdbcType=VARCHAR}

